// BAD: Using string concatenation for SQL queries (SQL Injection vulnerable)
// Also using Runtime.exec with unvalidated input (Command Injection vulnerable)
import java.sql.*;
import javax.servlet.http.*;

public class UserLookupServlet extends HttpServlet {
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) {
        String userId = req.getParameter("userId"); // attacker-controlled
        String fileArg = req.getParameter("file");  // attacker-controlled

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "user", "pass");
             Statement stmt = conn.createStatement()) {

            // vulnerable: concatenating untrusted input into SQL query
            String sql = "SELECT id, username, email FROM users WHERE id = " + userId;
            ResultSet rs = stmt.executeQuery(sql);
            while (rs.next()) {
                resp.getWriter().println("User: " + rs.getString("username"));
            }

            // vulnerable: unvalidated input passed to system command
            // An attacker could pass file=; rm -rf / or similar depending on OS
            String cmd = "cat " + fileArg;
            Process p = Runtime.getRuntime().exec(cmd);
            p.waitFor();

        } catch (Exception e) {
            // Leaks internal details to client (information disclosure)
            try { resp.getWriter().println("Error: " + e.getMessage()); } catch (Exception ignore) {}
        }
    }
}
***
/*
GOOD: Use PreparedStatement to prevent SQL injection and validate inputs.
Also avoid Runtime.exec for file reads; use safe APIs. Limit error details.
*/
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;

public class UserLookupServletSafe extends HttpServlet {
    // Strict numeric pattern for ID validation
    private static final Pattern ID_PATTERN = Pattern.compile("^[0-9]{1,10}$");

    // Restrict file access to a known safe directory (allowlist approach)
    private static final Path SAFE_BASE = Paths.get("/var/app/readonly").toAbsolutePath().normalize();

    protected void doGet(HttpServletRequest req, HttpServletResponse resp) {
        String userIdParam = req.getParameter("userId");
        String fileParam = req.getParameter("file");

        // Validate and parse ID safely
        if (userIdParam == null || !ID_PATTERN.matcher(userIdParam).matches()) {
            sendBadRequest(resp, "Invalid userId");
            return;
        }
        long userId = Long.parseLong(userIdParam);

        // Optional: normalize and enforce path containment for file reads
        Path requested = SAFE_BASE; // default
        if (fileParam != null && !fileParam.isBlank()) {
            try {
                Path candidate = SAFE_BASE.resolve(fileParam).normalize();
                if (!candidate.startsWith(SAFE_BASE)) {
                    sendBadRequest(resp, "Invalid file path");
                    return;
                }
                requested = candidate;
            } catch (Exception e) {
                sendBadRequest(resp, "Invalid file path");
                return;
            }
        }

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "user", "pass");
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT id, username, email FROM users WHERE id = ?")) {

            // Use parameterized query to avoid SQL injection
            ps.setLong(1, userId);

            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    resp.getWriter().println("User: " + rs.getString("username"));
                } else {
                    resp.getWriter().println("User not found");
                }
            }

            // Read file content safely without spawning a shell
            if (requested != SAFE_BASE && Files.isRegularFile(requested)) {
                String content = Files.readString(requested, StandardCharsets.UTF_8);
                resp.getWriter().println("File content length: " + content.length());
            }

        } catch (SQLException sqle) {
            // Log server-side; return generic message to client
            log("Database error", sqle);
            sendServerError(resp);
        } catch (Exception e) {
            log("Unhandled error", e);
            sendServerError(resp);
        }
    }

    private void sendBadRequest(HttpServletResponse resp, String message) {
        try {
            resp.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            resp.getWriter().println(message);
        } catch (Exception ignore) {}
    }

    private void sendServerError(HttpServletResponse resp) {
        try {
            resp.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            resp.getWriter().println("An error occurred");
        } catch (Exception ignore) {}
    }
}

