// Example: Java servlet vulnerable to SQL Injection (vulnerable)
import java.io.IOException;
import java.sql.*;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;

@WebServlet("/login")
public class VulnLoginServlet extends HttpServlet {
  protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
    String user = req.getParameter("username");
    String pass = req.getParameter("password");

    // vulnerable: direct string concatenation into SQL lets attacker inject
    String sql = "SELECT id FROM users WHERE username = '" + user + "' AND password = '" + pass + "'";

    try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app", "app");
         Statement st = conn.createStatement();
         ResultSet rs = st.executeQuery(sql)) {

      if (rs.next()) {
        resp.getWriter().write("Login ok");
      } else {
        resp.getWriter().write("Bad login");
      }
    } catch (SQLException e) {
      resp.sendError(500, "DB error");
    }
  }
}
***
/*
  Fixed: Use PreparedStatement with placeholders to prevent SQL injection.
  Also avoid disclosing errors and use constant-time password checks if storing hashes.
*/
import java.io.IOException;
import java.sql.*;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;

@WebServlet("/login")
public class SafeLoginServlet extends HttpServlet {
  protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
    String user = req.getParameter("username");
    String pass = req.getParameter("password");

    // Basic input length checks (optional defense-in-depth, not a sole fix)
    if (user == null || pass == null || user.length() > 64 || pass.length() > 256) {
      resp.sendError(400, "Invalid input");
      return;
    }

    String sql = "SELECT password_hash FROM users WHERE username = ?";

    try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app", "app");
         PreparedStatement ps = conn.prepareStatement(sql)) {

      ps.setString(1, user);             // Use parameter binding
      try (ResultSet rs = ps.executeQuery()) {
        if (!rs.next()) {
          // Generic message to avoid enumeration
          resp.getWriter().write("Bad login");
          return;
        }
        String storedHash = rs.getString(1);

        // Example using BCrypt (assume BCrypt library on classpath)
        boolean ok = org.mindrot.jbcrypt.BCrypt.checkpw(pass, storedHash);

        if (ok) {
          resp.getWriter().write("Login ok");
        } else {
          resp.getWriter().write("Bad login");
        }
      }
    } catch (SQLException e) {
      // Do not leak DB details
      resp.sendError(500, "Server error");
    }
  }
}

