        },
        {
          "dimension": "Testing",
          "descriptors": {
            "1": "Sparse or flaky tests.",
            "3": "Adequate unit/integration tests with meaningful coverage.",
            "5": "Comprehensive, reliable tests incl. property/fuzz where relevant."
          }
        },
        {
          "dimension": "Performance & Efficiency",
          "descriptors": {
            "1": "Introduces inefficiencies; ignores profiling.",
            "3": "Meets performance requirements; profiles when needed.",
            "5": "Optimizes proactively with data; balances trade-offs well."
          }
        }
      ]
    },
    {
      "name": "System Design",
      "weight": 0.15,
      "criteria": [
        {
          "dimension": "Architecture",
          "descriptors": {
            "1": "Tightly coupled, short-term fixes.",
            "3": "Modular, scalable for current needs.",
            "5": "Evolvable, resilient designs anticipating growth."
          }
        },
        {
          "dimension": "Trade-offs",
          "descriptors": {
            "1": "Chooses tools without rationale.",
            "3": "Explains trade-offs clearly.",
            "5": "Consistently selects pragmatic, cost-aware solutions."
          }
        },
        {
          "dimension": "Reliability & Observability",
          "descriptors": {
            "1": "Limited error handling/metrics.",
            "3": "Implements retries, alerts, dashboards.",
            "5": "Designs for SLOs, chaos readiness, and rapid recovery."
          }
        }
      ]
    },
    {
      "name": "Execution & Delivery",
      "weight": 0.2,
      "criteria": [
        {
          "dimension": "Planning & Estimation",
          "descriptors": {
            "1": "Unreliable estimates; frequent slips.",
            "3": "Reasonable scoping; delivers to plan.",
            "5": "Highly predictable; de-risks early; unblocker for others."
          }
        },
        {
          "dimension": "Speed with Quality",
          "descriptors": {
            "1": "Slow and/or high rework.",
            "3": "Timely delivery with low rework.",
            "5": "Rapid iterations with sustained quality."
          }
        },
        {
          "dimension": "Ownership",
          "descriptors": {
            "1": "Requires close supervision.",
            "3": "Owns tasks end-to-end; follows through.",
            "5": "Owns outcomes; drives cross-team initiatives."
          }
        }
      ]
    },
    {
      "name": "Collaboration & Communication",
      "weight": 0.15,
      "criteria": [
        {
            "dimension": "Team Communication",
            "descriptors": {
              "1": "Unclear updates; surprises stakeholders.",
              "3": "Regular, concise updates; manages expectations.",
              "5": "Proactive alignment; clarifies ambiguity early."
            }
        },
        {
          "dimension": "Code Review",
          "descriptors": {
            "1": "Superficial or blocking without guidance.",
            "3": "Actionable, respectful feedback; timely reviews.",
            "5": "Raises team bar; mentors via review."
          }
        },
        {
          "dimension": "Cross-Functional",
          "descriptors": {
            "1": "Struggles to work with PM/Design/Ops.",
            "3": "Collaborates effectively; integrates feedback.",
            "5": "Facilitates alignment; resolves conflicts constructively."
          }
        }
      ]
    },
    {
      "name": "Security & Compliance",
      "weight": 0.1,
      "criteria": [
        {
          "dimension": "Secure Coding",
          "descriptors": {
            "1": "Introduces common vulnerabilities.",
            "3": "Follows best practices; uses linters/Scanners.",
            "5": "Threat-models; leads remediations and training."
          }
        },
        {
          "dimension": "Data Privacy & Compliance",
          "descriptors": {
            "1": "Ignores data handling policies.",
            "3": "Implements retention, access control properly.",
            "5": "Designs compliant systems; audits and improves processes."
          }
        }
      ]
    },
    {
      "name": "DevOps & Operational Excellence",
      "weight": 0.1,
      "criteria": [
        {
          "dimension": "CI/CD & Automation",
          "descriptors": {
            "1": "Manual deployments; brittle pipelines.",
            "3": "Stable pipelines; automates common tasks.",
            "5": "Optimizes pipelines; reduces MTTR and lead time."
          }
        },
        {
          "dimension": "Monitoring & On-call",
          "descriptors": {
            "1": "Limited alerts; slow incident response.",
            "3": "Meaningful alerts; participates effectively on-call.",
            "5": "Improves runbooks; drives postmortems and reliability."
          }
        }
      ]
    },
    {
      "name": "Impact & Business Value",
      "weight": 0.1,
      "criteria": [
        {
          "dimension": "Customer Focus",
          "descriptors": {
            "1": "Builds features misaligned with needs.",
            "3": "Validates with users/PM; delivers value.",
            "5": "Anticipates needs; influences roadmap with insights."
          }
        },
        {
          "dimension": "Measurable Outcomes",
          "descriptors": {
            "1": "Unclear impact.",
            "3": "Links work to metrics (e.g., latency, revenue, CSAT).",
            "5": "Drives significant metric movement with evidence."
          }
        }
      ]
    },
    {
      "name": "Growth & Leadership",
      "weight": 0.05,
      "criteria": [
        {
          "dimension": "Learning & Adaptability",
          "descriptors": {
            "1": "Resistant to feedback; slow to learn.",
            "3": "Incorporates feedback; learns new tools as needed.",
            "5": "Continuously upskills; shares knowledge widely."
          }
        },
        {
          "dimension": "Mentorship & Influence",
          "descriptors": {
            "1": "Limited support to peers.",
            "3": "Helps peers; documents learnings.",
            "5": "Mentors formally; uplifts team practices."
          }
        }
      ]
    }
  ],
  "rating_method": {
    "instructions": [
      "For each dimension, assign a score from 1 to 5 using descriptors.",
      "Compute competency score as the average of its dimensions.",
      "Multiply each competency score by its weight.",
      "Sum weighted scores to get the overall rating (1.0 to 5.0).",
      "Add qualitative notes and evidence for top strengths and growth areas."
    ],
    "example": {
      "competency_scores": {
        "Code Quality": 3.8,
        "System Design": 3.2,
        "Execution & Delivery": 4.0,
        "Collaboration & Communication": 3.5,
        "Security & Compliance": 3.0,
        "DevOps & Operational Excellence": 3.6,
        "Impact & Business Value": 3.4,
        "Growth & Leadership": 3.7
      },
      "overall_rating": 3.59
    }
  },
  "evidence_checklist": [
    "Links to PRs, design docs, and ADRs.",
    "Test coverage reports and CI logs.",
    "Incident reports, postmortems, on-call metrics (MTTA/MTTR).",
    "Performance dashboards (latency, error rate, throughput).",
    "Security scans, threat models, compliance checklists.",
    "Stakeholder feedback (PM, Design, QA, Support)."
  ],
  "calibration_guidelines": [
    "Use the same scale across levels; expectations differ by scope and autonomy.",
    "Normalize across reviewers with example artifacts.",
    "Avoid recency bias; consider the full review period.",
    "Reward impact and sustainable practices, not heroics."
  ]
}
